B.b9g=new A.J(B.bW,["Gugup jelang ujian atau presentasi","\u092a\u0930\u0940\u0915\u094d\u0937\u093e \u0935\u093e \u092a\u094d\u0930\u0938\u094d\u0924\u0941\u0924\u093f\u092e\u093e \u0927\u0947\u0930\u0948 \u0928\u0930\u094d\u092d\u0938 \u091b\u0941","Imtihon yoki taqdimotdan juda hayajondaman"],t.w)
B.b9m=new A.J(B.bW,["Sulit fokus pada PR dan belajar","\u0917\u0943\u0939\u0915\u093e\u0930\u094d\u092f \u0930 \u092a\u0922\u093e\u0907\u092e\u093e \u0927\u094d\u092f\u093e\u0928 \u091c\u093e\u0901\u0926\u0948\u0928","Uy vazifasi va o\u2018qishga diqqat qilish qiyin"],t.w)
B.b9d=new A.J(B.bW,["Apa bakat terpendamku yang sebenarnya?","\u092e\u0947\u0930\u094b \u0938\u093e\u0901\u091a\u094d\u091a\u0948 \u0932\u0941\u0915\u0947\u0915\u094b \u092a\u094d\u0930\u0924\u093f\u092d\u093e \u0915\u0947 \u0939\u094b?","Mening haqiqiy yashirin iqtidorim nima?"],t.w)
B.b9o=new A.J(B.bW,["Takut dimarahi karena melakukan kesalahan","\u0917\u0932\u094d\u0924\u0940 \u0917\u0930\u0947\u0930 \u0939\u092a\u094d\u0915\u093f\u0928\u0947 \u0921\u0930 \u0932\u093e\u0917\u094d\u091b","Xato qilib, tanbeh olishdan qo\u2018rqaman"],t.w)
B.b9B=new A.J(B.bW,["Bertengkar dengan teman dan ingin berbaikan","\u0938\u093e\u0925\u0940\u0938\u0901\u0917 \u091d\u0917\u0921\u093e \u092d\u092f\u094b, \u092e\u093f\u0932\u094d\u0928 \u091a\u093e\u0939\u0928\u094d\u091b\u0941","Do\u2018stim bilan urishib qoldim, yarashmoqchiman"],t.w)
B.b9j=new A.J(B.bW,["Terlalu malu menyapa teman baru","\u0928\u092f\u093e\u0901 \u0938\u093e\u0925\u0940\u0932\u093e\u0908 \u092c\u094b\u0932\u094d\u0928 \u0932\u093e\u091c \u0932\u093e\u0917\u094d\u091b","Yangi do\u2018stimga gapirishga uyalaman"],t.w)
B.b9D=new A.J(B.bW,["Ingin membahagiakan keluargaku","\u092a\u0930\u093f\u0935\u093e\u0930\u0932\u093e\u0908 \u0916\u0941\u0938\u0940 \u092c\u0928\u093e\u0909\u0928 \u091a\u093e\u0939\u0928\u094d\u091b\u0941","Oilamni xursand qilmoqchiman"],t.w)
B.b9w=new A.J(B.bW,["Pujian terbaik untuk membuat teman tersenyum","\u0938\u093e\u0925\u0940\u0932\u093e\u0908 \u0939\u0938\u093e\u0909\u0928\u0947 \u0909\u0924\u094d\u0924\u092e \u092a\u094d\u0930\u0936\u0902\u0938\u093e","Do\u2018stimni kuldirish uchun eng yaxshi maqtov"],t.w)
B.b97=new A.J(B.bW,["Bimbang antara dua pilihan","\u0926\u0941\u0908 \u0935\u093f\u0915\u0932\u094d\u092a\u092c\u0940\u091a \u0926\u094b\u0927\u093e\u0930\u092e\u093e \u091b\u0941","Ikki variant o\u2018rtasida ikkilanaman"],t.w)
B.b9b=new A.J(B.bW,["Misi kecil keberuntunganku hari ini","\u0906\u091c\u0915\u094b \u092e\u0947\u0930\u094b \u092d\u093e\u0917\u094d\u092f\u0936\u093e\u0932\u0940 \u0938\u093e\u0928\u094b \u092e\u093f\u0938\u0928","Bugungi shaxsiy omadli kichik missiyam"],t.w)
B.b9t=new A.J(B.bW,["Cara menjaga barang berharga agar tidak hilang","\u092e\u0939\u0924\u094d\u0924\u094d\u0935\u092a\u0942\u0930\u094d\u0923 \u0938\u093e\u092e\u093e\u0928 \u0928\u0939\u0930\u093e\u0909\u0928\u0947 \u0909\u092a\u093e\u092f","Qimmatbaho narsalarni yo\u2018qotmaslik yo\u2018li"],t.w)
B.b9q=new A.J(B.bW,["Akankah ada kejutan menyenangkan hari ini?","\u0906\u091c \u0916\u0941\u0938\u0940\u0915\u094b \u0905\u091a\u092e\u094d\u092e \u0939\u0941\u0928\u0947\u091b?","Bugun yoqimli syurpriz bo\u2018ladimi?"],t.w)
B.b9r=new A.J(B.bW,["Kepercayaan diri menurun dan merasa lesu","\u0906\u0924\u094d\u092e\u0935\u093f\u0936\u094d\u0935\u093e\u0938 \u0918\u091f\u0947\u0930 \u0928\u093f\u0930\u093e\u0936 \u091b\u0941","Ishonchim pasayib, tushkunlikka tushdim"],t.w)
B.b96=new A.J(B.bW,["Cara menenangkan diri saat kesal atau marah","\u0930\u093f\u0938 \u0935\u093e \u0926\u0941\u0903\u0916\u092e\u093e \u0936\u093e\u0928\u094d\u0924 \u0939\u0941\u0928\u0947 \u0924\u0930\u093f\u0915\u093e","Jahlim chiqqanda yoki xafa bo\u2018lganda tinchlanish yo\u2018li"],t.w)
B.b9i=new A.J(B.bW,["Butuh semangat untuk mengejar mimpiku","\u0938\u092a\u0928\u093e \u092a\u091b\u094d\u092f\u093e\u0909\u0928 \u0939\u094c\u0938\u0932\u093e \u091a\u093e\u0939\u093f\u0928\u094d\u091b","Orzuim ortidan borish uchun dalda kerak"],t.w)
B.b9y=new A.J(B.bW,["Terlalu banyak pikiran hingga sulit tidur","\u0927\u0947\u0930\u0948 \u0938\u094b\u091a\u093e\u0907\u0932\u0947 \u0928\u093f\u0926\u094d\u0930\u093e \u0932\u093e\u0917\u094d\u0926\u0948\u0928","Ko\u2018p o\u2018ylar tufayli uxlay olmayapman"],t.w)
B.bfV=new A.J(B.fb,[B.b9g,B.b9m,B.b9d,B.b9o,B.b9B,B.b9j,B.b9D,B.b9w,B.b97,B.b9b,B.b9t,B.b9q,B.b9r,B.b96,B.b9i,B.b9y],t.vb)
B.b9f=new A.J(B.bW,["Kkaebi! Hari ini aku ada ujian/presentasi penting dan sangat gugup. Kasih rahasia biar tenang, dong!","\u0915\u094d\u0915\u0947\u092c\u0940! \u0906\u091c \u092e\u0947\u0930\u094b \u092e\u0939\u0924\u094d\u0924\u094d\u0935\u092a\u0942\u0930\u094d\u0923 \u092a\u0930\u0940\u0915\u094d\u0937\u093e/\u092a\u094d\u0930\u0938\u094d\u0924\u0941\u0924\u093f \u091b \u0930 \u0927\u0947\u0930\u0948 \u0928\u0930\u094d\u092d\u0938 \u091b\u0941\u0964 \u0936\u093e\u0928\u094d\u0924 \u0939\u0941\u0928\u0947 \u0909\u092a\u093e\u092f \u092d\u0928\u094d\u0928\u0941\u0939\u094b\u0938\u094d!","Kkaebi! Bugun muhim imtihon/taqdimotim bor va juda hayajondaman. Tinchlanish sirini aytib ber!"],t.w)
B.b99=new A.J(B.bW,["Kkaebi! Aku harus belajar dan mengerjakan PR, tapi pikiranku melayang. Gimana cara fokus?","\u0915\u094d\u0915\u0947\u092c\u0940! \u092a\u0922\u094d\u0928 \u0930 \u0917\u0943\u0939\u0915\u093e\u0930\u094d\u092f \u0917\u0930\u094d\u0928\u0941\u092a\u0930\u094d\u091b \u0924\u0930 \u0927\u094d\u092f\u093e\u0928 \u092d\u093e\u0917\u093f\u0930\u0939\u0928\u094d\u091b\u0964 \u090f\u0915\u093e\u0917\u094d\u0930 \u0939\u0941\u0928\u0947 \u0909\u092a\u093e\u092f \u0915\u0947 \u0939\u094b?","Kkaebi! O\u2018qishim va uy vazifam bor, lekin xayolim chalg\u2018iydi. Qanday diqqat qilaman?"],t.w)
B.b9n=new A.J(B.bW,["Kkaebi! Bakat apa yang aku miliki? Aku ingin tahu apa yang bisa aku lakukan dengan baik!","\u0915\u094d\u0915\u0947\u092c\u0940! \u092e\u0938\u0901\u0917 \u0915\u0941\u0928 \u092a\u094d\u0930\u0924\u093f\u092d\u093e \u091b? \u092e \u0915\u0947 \u0930\u093e\u092e\u094d\u0930\u094b \u0917\u0930\u094d\u0928 \u0938\u0915\u094d\u091b\u0941 \u091c\u093e\u0928\u094d\u0928 \u091a\u093e\u0939\u0928\u094d\u091b\u0941!","Kkaebi! Menda qanday iqtidor bor? Nima ishni yaxshi qila olishimni bilmoqchiman!"],t.w)
B.b9a=new A.J(B.bW,["Kkaebi! Aku baru melakukan kesalahan dan takut dimarahi. Aku harus bagaimana?","\u0915\u094d\u0915\u0947\u092c\u0940! \u092e\u0948\u0932\u0947 \u090f\u0909\u091f\u093e \u0917\u0932\u094d\u0924\u0940 \u0917\u0930\u0947\u0902 \u0930 \u0939\u092a\u094d\u0915\u093f\u0928\u0947 \u0921\u0930\u0932\u0947 \u091b\u091f\u092a\u091f\u0940 \u092d\u0907\u0930\u0939\u0947\u0915\u094b \u091b\u0964 \u0915\u0947 \u0917\u0930\u0942\u0901?","Kkaebi! Men xato qildim va tanbeh olishdan qo\u2018rqyapman. Nima qilay?"],t.w)
B.b9C=new A.J(B.bW,["Kkaebi, aku bertengkar dengan teman karena hal kecil. Bagaimana cara mendekati dan berbaikan?","\u0915\u094d\u0915\u0947\u092c\u0940, \u0938\u093e\u0925\u0940\u0938\u0901\u0917 \u0938\u093e\u0928\u094b \u0915\u0941\u0930\u093e\u092e\u093e \u091d\u0917\u0921\u093e \u092d\u092f\u094b\u0964 \u092a\u0939\u093f\u0932\u0947 \u092a\u0941\u0917\u0947\u0930 \u0915\u0938\u0930\u0940 \u092e\u093f\u0932\u094d\u0928\u0947?","Kkaebi, do\u2018stim bilan arzimagan narsa uchun urishdim. Qanday qilib birinchi bo\u2018lib yarashaman?"],t.w)
B.b9A=new A.J(B.bW,["Kkaebi, ada teman yang ingin aku dekati, tapi aku terlalu malu. Beri aku keberanian!","\u0915\u094d\u0915\u0947\u092c\u0940, \u0928\u091c\u093f\u0915 \u0939\u0941\u0928 \u091a\u093e\u0939\u0947\u0915\u094b \u0938\u093e\u0925\u0940 \u091b \u0924\u0930 \u0932\u093e\u091c\u0932\u0947 \u092c\u094b\u0932\u094d\u0928 \u0938\u0915\u094d\u0926\u093f\u0928\u0964 \u0938\u093e\u0939\u0938 \u0926\u093f\u0928\u0941\u0939\u094b\u0938\u094d!","Kkaebi, yaqinlashmoqchi bo\u2018lgan do\u2018stim bor, lekin uyalaman. Menga jasorat ber!"],t.w)
B.b9p=new A.J(B.bW,["Kkaebi, ada ide kejutan kecil yang bisa membahagiakan orang tua atau keluargaku?","\u0915\u094d\u0915\u0947\u092c\u0940, \u0906\u092e\u093e\u092c\u093e\u092c\u0941 \u0935\u093e \u092a\u0930\u093f\u0935\u093e\u0930\u0932\u093e\u0908 \u0916\u0941\u0938\u0940 \u092c\u0928\u093e\u0909\u0928\u0947 \u0930\u093e\u092e\u094d\u0930\u094b \u0905\u091a\u092e\u094d\u092e\u0915\u094b \u0909\u092a\u093e\u092f \u091b?","Kkaebi, ota-onam yoki oilamni xursand qiladigan kichik syurpriz g\u2018oyasi bormi?"],t.w)
B.b9x=new A.J(B.bW,["Kkaebi, ajari aku pujian ajaib yang bisa membuat teman merasa luar biasa!","\u0915\u094d\u0915\u0947\u092c\u0940, \u0938\u093e\u0925\u0940\u0932\u093e\u0908 \u0916\u0941\u0938\u0940 \u092c\u0928\u093e\u0909\u0928\u0947 \u091c\u093e\u0926\u0941\u0908 \u092a\u094d\u0930\u0936\u0902\u0938\u093e \u0917\u0930\u094d\u0928\u0947 \u0924\u0930\u093f\u0915\u093e \u0938\u093f\u0915\u093e\u0909\u0928\u0941\u0939\u094b\u0938\u094d!","Kkaebi, do\u2018stimni xursand qiladigan sehrli maqtov aytishni o\u2018rgat!"],t.w)
B.b9u=new A.J(B.bW,["Kkaebi! Aku sedang bimbang antara dua pilihan. Bimbing aku dengan kebijaksanaanmu!","\u0915\u094d\u0915\u0947\u092c\u0940! \u092e \u0926\u0941\u0908 \u0935\u093f\u0915\u0932\u094d\u092a\u092e\u093e \u0905\u0932\u092e\u0932\u093f\u090f\u0915\u094b \u091b\u0941\u0964 \u0924\u093f\u092e\u094d\u0930\u094b \u092c\u0941\u0926\u094d\u0927\u093f\u0932\u0947 \u092e\u093e\u0930\u094d\u0917 \u0926\u0947\u0916\u093e\u090a!","Kkaebi! Ikki tanlov o\u2018rtasida ikkilanaman. Donoliging bilan yo\u2018l ko\u2018rsat!"],t.w)
B.b9c=new A.J(B.bW,["Kkaebi, tentukan satu misi kecil hari ini yang bisa mendatangkan keberuntungan besar!","\u0915\u094d\u0915\u0947\u092c\u0940, \u0906\u091c \u0920\u0942\u0932\u094b \u092d\u093e\u0917\u094d\u092f \u0932\u094d\u092f\u093e\u0909\u0928\u0947 \u090f\u0909\u091f\u093e \u0938\u093e\u0928\u094b \u092e\u093f\u0938\u0928 \u0924\u094b\u0915\u093f\u0926\u093f\u0928\u0941\u0939\u094b\u0938\u094d!","Kkaebi, bugun katta omad keltiradigan bitta kichik missiyani belgilab ber!"],t.w)
B.b98=new A.J(B.bW,["Kkaebi, aku takut barang-barangku sering hilang. Kasih tips kebiasaan merapikan!","\u0915\u094d\u0915\u0947\u092c\u0940, \u092e\u0947\u0930\u093e \u0938\u093e\u092e\u093e\u0928 \u0939\u0930\u093e\u0909\u0928\u0947 \u0921\u0930 \u0932\u093e\u0917\u094d\u091b\u0964 \u0938\u0901\u092d\u093e\u0932\u0947\u0930 \u0930\u093e\u0916\u094d\u0928\u0947 \u092c\u093e\u0928\u0940\u0915\u094b \u0938\u0941\u091d\u093e\u0935 \u0926\u093f\u0928\u0941\u0939\u094b\u0938\u094d!","Kkaebi, narsalarim yo\u2018qolib qolishidan qo\u2018rqaman. Ular bilan yurish odati haqida maslahat ber!"],t.w)
B.b95=new A.J(B.bW,["Kkaebi, akankah hari ini ada kejutan menyenangkan yang ajaib untukku?","\u0915\u094d\u0915\u0947\u092c\u0940, \u0906\u091c \u092e\u0947\u0930\u094b \u0932\u093e\u0917\u093f \u091c\u093e\u0926\u0941\u0908 \u0916\u0941\u0938\u0940\u0915\u094b \u0905\u091a\u092e\u094d\u092e \u0906\u0909\u0928\u0947\u091b?","Kkaebi, bugun menga sehrli yoqimli syurpriz keladimi?"],t.w)
B.b94=new A.J(B.bW,["Kkaebi, hari ini aku lemas dan kurang percaya diri. Isi aku dengan kekuatanmu!","\u0915\u094d\u0915\u0947\u092c\u0940, \u0906\u091c \u092e\u0932\u093e\u0908 \u090a\u0930\u094d\u091c\u093e \u0930 \u0906\u0924\u094d\u092e\u0935\u093f\u0936\u094d\u0935\u093e\u0938 \u091b\u0948\u0928\u0964 \u0924\u093f\u092e\u094d\u0930\u094b \u0936\u0915\u094d\u0924\u093f \u0926\u093f\u0928\u0941\u0939\u094b\u0938\u094d!","Kkaebi, bugun kuchim va ishonchim yo\u2018q. Menga o\u2018z kuchingdan ber!"],t.w)
B.b9l=new A.J(B.bW,["Kkaebi, ada hal yang membuatku kesal dan hatiku mendidih. Bagaimana cara meredakannya?","\u0915\u094d\u0915\u0947\u092c\u0940, \u092e\u0928 \u0916\u093f\u0928\u094d\u0928 \u091b \u0930 \u0930\u093f\u0938 \u0909\u0920\u093f\u0930\u0939\u0947\u0915\u094b \u091b\u0964 \u0936\u093e\u0928\u094d\u0924 \u0915\u0938\u0930\u0940 \u0939\u0941\u0928\u0947?","Kkaebi, xafa bo\u2018lib, ichim qaynayapti. Qanday tinchlanaman?"],t.w)
B.b9s=new A.J(B.bW,["Kkaebi, aku punya mimpi besar! Aku ingin mendengar sorakan penuh semangat darimu!","\u0915\u094d\u0915\u0947\u092c\u0940, \u092e\u0947\u0930\u094b \u0920\u0942\u0932\u094b \u0938\u092a\u0928\u093e \u091b! \u0924\u093f\u092e\u094d\u0930\u094b \u0939\u094c\u0938\u0932\u093e\u092d\u0930\u093e \u0936\u0941\u092d\u0915\u093e\u092e\u0928\u093e \u0938\u0941\u0928\u094d\u0928 \u091a\u093e\u0939\u0928\u094d\u091b\u0941!","Kkaebi, mening katta orzuim bor! Sendan dalda to\u2018la tilak eshitmoqchiman!"],t.w)
B.b9k=new A.J(B.bW,["Kkaebi, aku sudah di kasur tapi pikiranku ramai dan sulit tidur. Beri aku mantra tidur nyenyak!","\u0915\u094d\u0915\u0947\u092c\u0940, \u0913\u091b\u094d\u092f\u093e\u0928\u092e\u093e \u092a\u0932\u094d\u091f\u093f\u090f\u0901 \u0924\u0930 \u091a\u093f\u0928\u094d\u0924\u093e\u0932\u0947 \u0928\u093f\u0926\u094d\u0930\u093e \u0932\u093e\u0917\u094d\u0926\u0948\u0928\u0964 \u0930\u093e\u092e\u094d\u0930\u094b \u0928\u093f\u0926\u094d\u0930\u093e\u0915\u094b \u092e\u0928\u094d\u0924\u094d\u0930 \u0926\u093f\u0928\u0941\u0939\u094b\u0938\u094d!","Kkaebi, to\u2018shakda yotdim, lekin xayollarim ko\u2018p va uxlay olmayapman. Yaxshi uyqu duosini ber!"],t.w)
